        int[] x = new int[n];
        for (int i = 0; i < n; i++) {
            x[i] = fs.nextInt();
        }

        u = new long[n];
        v = new long[n];

        minU = Long.MAX_VALUE;
        maxU = Long.MIN_VALUE;
        minV = Long.MAX_VALUE;
        maxV = Long.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            int y = fs.nextInt();
            long ui = (long) x[i] + y;
            long vi = (long) x[i] - y;

            u[i] = ui;
            v[i] = vi;

            if (ui < minU) minU = ui;
            if (ui > maxU) maxU = ui;
            if (vi < minV) minV = vi;
            if (vi > maxV) maxV = vi;
        }

        long lo = 0;
        long hi = Math.max(maxU - minU, maxV - minV);

        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (can(mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }

        System.out.println(lo);
    }

    static boolean can(long d) {
        if (check(minU, minU + d, minV, minV + d, d)) return true;
        if (check(minU, minU + d, maxV - d, maxV, d)) return true;
        if (check(maxU - d, maxU, minV, minV + d, d)) return true;
        if (check(maxU - d, maxU, maxV - d, maxV, d)) return true;
        return false;
    }

    static boolean check(long uL, long uR, long vL, long vR, long d) {
        long rMinU = Long.MAX_VALUE, rMaxU = Long.MIN_VALUE;
